from collections import deque

def find_reachable_states(initial_set, target_count, extra=5, max_states=1000000):
    lo = -extra; hi = max(r for r,c in initial_set) + extra
    lo_c = -extra; hi_c = max(c for r,c in initial_set) + extra
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    initial = frozenset(initial_set)
    visited = {initial: None}
    queue = deque([initial])
    results = []
    count = 0
    while queue and count < max_states:
        state = queue.popleft(); count += 1
        if len(state) == target_count:
            results.append(state); continue
        if len(state) < target_count: continue
        for (r,c) in list(state):
            for dr,dc in dirs:
                mid=(r+dr,c+dc); dest=(r+2*dr,c+2*dc)
                if mid in state and dest not in state:
                    if lo<=dest[0]<=hi and lo_c<=dest[1]<=hi_c:
                        ns = frozenset((state - {(r,c),mid}) | {dest})
                        if ns not in visited:
                            visited[ns] = (state, ((r,c),dest))
                            queue.append(ns)
    return results

