# (n+3)×(n+3) -> n×n + 2 extra pieces -> 1

from collections import deque
import random

def can_reduce_to_one(initial_set, extra=12, max_states=5000000):
    """BFS to check if reducible to 1"""
    lo = -extra; hi = max(r for r,c in initial_set) + extra
    lo_c = -extra; hi_c = max(c for r,c in initial_set) + extra
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    initial = frozenset(initial_set)
    visited = {initial}
    queue = deque([initial])
    count = 0
    while queue and count < max_states:
        state = queue.popleft(); count += 1
        if len(state) == 1:
            return True
        for (r,c) in list(state):
            for dr,dc in dirs:
                mid=(r+dr,c+dc); dest=(r+2*dr,c+2*dc)
                if mid in state and dest not in state:
                    if lo<=dest[0]<=hi and lo_c<=dest[1]<=hi_c:
                        ns = frozenset((state - {(r,c),mid}) | {dest})
                        if ns not in visited:
                            visited.add(ns)
                            queue.append(ns)
    return False

def random_reduce(initial_set, max_attempts=500000, extra=15):
    """Random search to reduce to 1"""
    lo = -extra; hi = max(r for r,c in initial_set) + extra
    lo_c = -extra; hi_c = max(c for r,c in initial_set) + extra
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    for _ in range(max_attempts):
        state = set(initial_set)
        while len(state) > 1:
            valid = []
            for (r, c) in state:
                for dr, dc in dirs:
                    mid = (r+dr, c+dc)
                    dest = (r+2*dr, c+2*dc)
                    if mid in state and dest not in state:
                        if lo <= dest[0] <= hi and lo_c <= dest[1] <= hi_c:
                            valid.append(((r,c), mid, dest))
            if not valid:
                break
            move = random.choice(valid)
            (r,c), mid, dest = move
            state.discard((r,c)); state.discard(mid); state.add(dest)
        if len(state) == 1:
            return True
    return False

# Verify n=4,5 can be reduced to 1 (base cases)
for n in [4, 5]:
    block = set((r,c) for r in range(n) for c in range(n))
    result = random_reduce(block, max_attempts=500000, extra=15)
    print(f"n={n}: {'FOUND' if result else 'NOT FOUND'}")

# Verify 3 pieces in key configurations can be reduced to 1
configs = [
    {(0,0), (0,1), (0,3)},  # gap of 1
    {(0,0), (0,2), (0,3)},  # gap of 1 (other side)
    {(0,0), (1,0), (3,0)},  # vertical gap
    {(0,0), (2,0), (3,0)},  # vertical gap (other side)
]
for i, cfg in enumerate(configs):
    result = can_reduce_to_one(cfg, extra=5, max_states=10000)
    print(f"Config {i} {sorted(cfg)}: {'YES' if result else 'NO'}")
